import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    matrix = []
    index = 1

    for i in range(n):
        row = list(map(float, data[index:index+n]))
        matrix.append(row)
        index += n

    # Create augmented matrix [A|I]
    aug = [[0.0] * (2 * n) for _ in range(n)]
    for i in range(n):
        for j in range(n):
            aug[i][j] = matrix[i][j]
        aug[i][i + n] = 1.0

    # Gaussian elimination with partial pivoting
    for col in range(n):
        # Find pivot
        max_row = col
        for row in range(col + 1, n):
            if abs(aug[row][col]) > abs(aug[max_row][col]):
                max_row = row

        if abs(aug[max_row][col]) < 1e-10:
            print(" Inverse does not exist")
            return

        # Swap rows
        aug[col], aug[max_row] = aug[max_row], aug[col]

        # Scale pivot row
        pivot = aug[col][col]
        for j in range(2 * n):
            aug[col][j] /= pivot

        # Eliminate column
        for row in range(n):
            if row != col:
                factor = aug[row][col]
                for j in range(2 * n):
                    aug[row][j] -= factor * aug[col][j]

    # Extract inverse matrix
    inv = [[aug[i][j + n] for j in range(n)] for i in range(n)]

    # Format output with 4 decimal places
    for row in inv:
        formatted = [f"{x:.4f}" for x in row]
        print(" ".join(formatted))

if __name__ == "__main__":
    main()
